Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>
  w (scale λ)
  <input type="range" id="lambdaSlider" min="0.3" max="3" step="0.1" value="2">
</label>
<label>
  <input type="checkbox" id="equivClass"> Show equivalence class
</label>
<button id="btnStep1">Step 1: Canonical embedding</button>
<button id="btnStep2">Step 2: Slide along ray</button>
<button id="btnStep3">Step 3: Equivalence class</button>
<div id="readout" style="font-size:12px;margin-top:4px;color:#333;"></div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── Element specs ──
// y-axis: Line + ConeGeometry(0.06,0.15) black, from (0,-2,0) to (0,2,0)
// x-axis: Line + ConeGeometry(0.06,0.15) black, from (0,0,-2) to (0,0,2)
// w-axis: Line + ConeGeometry(0.06,0.15) black, from (0,0,0) to (3.2,0,0), tick at X=1
// Heterogeneous plane: PlaneGeometry(4,4) at X=0, color #dfe8ea, opacity 0.45
// w=1 plane: PlaneGeometry(4,4) at X=1, wireframe/edges only, stroke #7a8a8d
// red 2D point: SphereGeometry(0.09) red #e02020 at (0, y, x)
// red canonical point: SphereGeometry(0.09) red at (1, y, x)
// red representative: SphereGeometry(0.09) red at (λ, λy, λx)
// connector: Line grey #888 from (0,y,x) to (1,y,x)
// dashed ray: LineDashedMaterial black from origin to (λ,λy,λx)
// equiv markers: TorusGeometry(0.12,0.02) orange #ff8800 at λ∈{0.5,1,2,3}

const DEFAULT_X = 0.6;
const DEFAULT_Y = 0.7;
let ptX = DEFAULT_X;
let ptY = DEFAULT_Y;
let lambda = 2;
let showEquiv = false;

// ── Axes ──
function makeArrow(from, to, color = 0x111111) {
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = dir.length();
  dir.normalize();
  const lineGeom = new THREE.BufferGeometry().setFromPoints([from, to]);
  const lineMat = new THREE.LineBasicMaterial({ color });
  const line = new THREE.Line(lineGeom, lineMat);
  scene.add(line);
  // Arrowhead
  const coneGeom = new THREE.ConeGeometry(0.06, 0.18, 8);
  const coneMat = new THREE.MeshBasicMaterial({ color });
  const cone = new THREE.Mesh(coneGeom, coneMat);
  cone.position.copy(to);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  scene.add(cone);
  return { line, cone };
}

// y-axis (vertical, +Y)
makeArrow(new THREE.Vector3(0, -2, 0), new THREE.Vector3(0, 2, 0));
// x-axis (receding, +Z)
makeArrow(new THREE.Vector3(0, 0, -2), new THREE.Vector3(0, 0, 2));
// w-axis (horizontal right, +X)
makeArrow(new THREE.Vector3(0, 0, 0), new THREE.Vector3(3.2, 0, 0));

// Tick mark at X=1 on w-axis
const tickGeom = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(1, -0.1, 0), new THREE.Vector3(1, 0.1, 0)
]);
const tickMat = new THREE.LineBasicMaterial({ color: 0x111111 });
scene.add(new THREE.Line(tickGeom, tickMat));

// ── Heterogeneous plane (X=0, the Y-Z plane) ──
const hetPlaneGeom = new THREE.PlaneGeometry(4, 4);
const hetPlaneMat = new THREE.MeshBasicMaterial({
  color: 0xdfe8ea, transparent: true, opacity: 0.45, side: THREE.DoubleSide
});
const hetPlane = new THREE.Mesh(hetPlaneGeom, hetPlaneMat);
hetPlane.position.set(0, 0, 0);
hetPlane.rotation.y = Math.PI / 2; // rotate so it lies in Y-Z plane (normal along X)
scene.add(hetPlane);

// ── w=1 plane (X=1, outline only) ──
const w1PlaneGeom = new THREE.PlaneGeometry(4, 4);
const w1Edges = new THREE.EdgesGeometry(w1PlaneGeom);
const w1LineMat = new THREE.LineBasicMaterial({ color: 0x7a8a8d });
const w1Outline = new THREE.LineSegments(w1Edges, w1LineMat);
w1Outline.position.set(1, 0, 0);
w1Outline.rotation.y = Math.PI / 2;
scene.add(w1Outline);

// ── Points ──
const pointMat = new THREE.MeshBasicMaterial({ color: 0xe02020 });
const pointGeom = new THREE.SphereGeometry(0.09, 16, 16);

const leftPoint = new THREE.Mesh(pointGeom, pointMat.clone());
leftPoint.position.set(0, ptY, ptX);
scene.add(leftPoint);

const canonPoint = new THREE.Mesh(pointGeom, pointMat.clone());
canonPoint.position.set(1, ptY, ptX);
scene.add(canonPoint);

const repPoint = new THREE.Mesh(pointGeom, pointMat.clone());
repPoint.position.set(lambda, lambda * ptY, lambda * ptX);
scene.add(repPoint);

// ── Connector line (grey, from left to canonical) ──
const connMat = new THREE.LineBasicMaterial({ color: 0x888888 });
const connGeom = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(0, ptY, ptX), new THREE.Vector3(1, ptY, ptX)
]);
const connLine = new THREE.Line(connGeom, connMat);
scene.add(connLine);

// ── Dashed ray from origin through canonical to representative ──
const dashMat = new THREE.LineDashedMaterial({ color: 0x111111, dashSize: 0.12, gapSize: 0.08 });
const dashGeom = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(0, 0, 0), new THREE.Vector3(lambda, lambda * ptY, lambda * ptX)
]);
const dashLine = new THREE.Line(dashGeom, dashMat);
dashLine.computeLineDistances();
scene.add(dashLine);

// ── Equivalence class markers (orange rings at λ ∈ {0.5, 1, 2, 3}) ──
const equivGroup = new THREE.Group();
const equivLambdas = [0.5, 1, 2, 3];
const equivRings = [];
equivLambdas.forEach(l => {
  const ringGeom = new THREE.TorusGeometry(0.14, 0.025, 8, 24);
  const ringMat = new THREE.MeshBasicMaterial({ color: 0xff8800 });
  const ring = new THREE.Mesh(ringGeom, ringMat);
  ring.position.set(l, l * ptY, l * ptX);
  // Orient ring to face camera-ish (billboard later or just leave default)
  equivGroup.add(ring);
  equivRings.push(ring);
});
equivGroup.visible = false;
scene.add(equivGroup);

// ── Labels ──
addLabel('<i>y</i>', new THREE.Vector3(0, 2.15, 0), { fontSize: '15px', bold: true });
addLabel('<i>x</i>', new THREE.Vector3(0, 0.15, 2.15), { fontSize: '15px', bold: true });
addLabel('<i>w</i>', new THREE.Vector3(3.35, -0.15, 0), { fontSize: '15px', bold: true });
addLabel('1', new THREE.Vector3(1, -0.25, 0), { fontSize: '13px' });
addLabel('Heterogeneous', new THREE.Vector3(-0.3, 1.2, -1.2), { fontSize: '13px', color: '#333' });
addLabel('Homogeneous', new THREE.Vector3(2.5, 1.0, 0.8), { fontSize: '13px', color: '#333' });

const lblLeft = addLabel('(<i>x</i>,<i>y</i>)', new THREE.Vector3(0, ptY + 0.2, ptX), { fontSize: '13px' });
const lblCanon = addLabel('(<i>x</i>,<i>y</i>,1)', new THREE.Vector3(1, ptY - 0.25, ptX), { fontSize: '13px' });
const lblRep = addLabel('(λ<i>x</i>,λ<i>y</i>,λ)', new THREE.Vector3(lambda, lambda * ptY + 0.2, lambda * ptX), { fontSize: '13px' });

// ── Readout ──
const readoutDiv = document.getElementById('readout');
function updateReadout() {
  const rx = (lambda * ptX / lambda).toFixed(2);
  const ry = (lambda * ptY / lambda).toFixed(2);
  readoutDiv.innerHTML = `(x/w, y/w) = (${rx}, ${ry})`;
}
updateReadout();

// ── Update functions ──
function updateScene() {
  // Update left point
  leftPoint.position.set(0, ptY, ptX);
  // Update canonical point
  canonPoint.position.set(1, ptY, ptX);
  // Update representative
  repPoint.position.set(lambda, lambda * ptY, lambda * ptX);
  // Update connector
  const cPos = connLine.geometry.attributes.position;
  cPos.setXYZ(0, 0, ptY, ptX);
  cPos.setXYZ(1, 1, ptY, ptX);
  cPos.needsUpdate = true;
  // Update dashed ray
  const dPos = dashLine.geometry.attributes.position;
  dPos.setXYZ(0, 0, 0, 0);
  dPos.setXYZ(1, lambda, lambda * ptY, lambda * ptX);
  dPos.needsUpdate = true;
  dashLine.computeLineDistances();
  // Update equiv rings
  equivRings.forEach((ring, i) => {
    const l = equivLambdas[i];
    ring.position.set(l, l * ptY, l * ptX);
  });
  // Update labels
  lblLeft.pos.set(0, ptY + 0.2, ptX);
  lblCanon.pos.set(1, ptY - 0.25, ptX);
  lblRep.pos.set(lambda, lambda * ptY + 0.2, lambda * ptX);
  // Update readout
  updateReadout();
  // Equiv coloring
  if (showEquiv) {
    leftPoint.material.color.set(0xff8800);
    canonPoint.material.color.set(0xff8800);
    repPoint.material.color.set(0xff8800);
  } else {
    leftPoint.material.color.set(0xe02020);
    canonPoint.material.color.set(0xe02020);
    repPoint.material.color.set(0xe02020);
  }
}

// ── UI Controls ──
const sliderEl = document.getElementById('lambdaSlider');
sliderEl.addEventListener('input', () => {
  lambda = parseFloat(sliderEl.value);
  updateScene();
});

const equivEl = document.getElementById('equivClass');
equivEl.addEventListener('change', () => {
  showEquiv = equivEl.checked;
  equivGroup.visible = showEquiv;
  updateScene();
});

// ── Drag interaction on Heterogeneous plane ──
const raycaster = new THREE.Raycaster();
const pointer2 = new THREE.Vector2();
let dragging = false;
const hetPlaneMath = new THREE.Plane(new THREE.Vector3(1, 0, 0), 0); // X=0 plane
const intersectPt = new THREE.Vector3();

canvas.addEventListener('pointerdown', (e) => {
  const rect = canvas.getBoundingClientRect();
  pointer2.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  pointer2.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  raycaster.setFromCamera(pointer2, camera);
  // Check if near left point
  const dist = raycaster.ray.distanceToPoint(leftPoint.position);
  if (dist < 0.2) {
    dragging = true;
    controls.enabled = false;
    e.preventDefault();
  }
});

canvas.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  const rect = canvas.getBoundingClientRect();
  pointer2.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  pointer2.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  raycaster.setFromCamera(pointer2, camera);
  if (raycaster.ray.intersectPlane(hetPlaneMath, intersectPt)) {
    ptY = THREE.MathUtils.clamp(intersectPt.y, -1.8, 1.8);
    ptX = THREE.MathUtils.clamp(intersectPt.z, -1.8, 1.8);
    updateScene();
  }
});

canvas.addEventListener('pointerup', () => {
  if (dragging) {
    dragging = false;
    controls.enabled = true;
  }
});

// ── Demo steps ──
function goToStep(step) {
  if (step === 1) {
    lambda = 1;
    sliderEl.value = '1';
    showEquiv = false;
    equivEl.checked = false;
    equivGroup.visible = false;
    updateScene();
  } else if (step === 2) {
    lambda = 2.5;
    sliderEl.value = '2.5';
    showEquiv = false;
    equivEl.checked = false;
    equivGroup.visible = false;
    updateScene();
  } else if (step === 3) {
    lambda = 2;
    sliderEl.value = '2';
    showEquiv = true;
    equivEl.checked = true;
    equivGroup.visible = true;
    updateScene();
  }
}

document.getElementById('btnStep1').addEventListener('click', () => goToStep(1));
document.getElementById('btnStep2').addEventListener('click', () => goToStep(2));
document.getElementById('btnStep3').addEventListener('click', () => goToStep(3));

// ── Register interactive elements ──
registerInteractive(leftPoint, {
  title: '2D Point (x, y)',
  body: 'This is the heterogeneous (standard Euclidean) representation. Drag it to change the point and watch the entire homogeneous ray swing.',
  tooltip: 'Drag to move the 2D point'
});
registerInteractive(canonPoint, {
  title: 'Canonical point (x, y, 1)',
  body: 'The canonical embedding of (x,y) into homogeneous coordinates: append w=1. This point always lies on the w=1 plane.',
  tooltip: 'Canonical homogeneous embedding'
});
registerInteractive(repPoint, {
  title: 'General representative (λx, λy, λ)',
  body: 'Any scalar multiple of (x,y,1) represents the same 2D point. Dividing by w always recovers (x,y).',
  tooltip: 'Scaled representative on the ray'
});

// ── Camera ──
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  heightFraction: 0.7
});

updateScene();
// @FIGURE_CODE_END

