  ray: addLabel('ray from Camera 1', C1.clone().lerp(P, 0.55).add(new THREE.Vector3(0.10, 0.17, 0.05)), { fontSize: '13px', color: '#d40000', background: 'rgba(255,255,255,0.80)' }),
  axes1: addLabel('coordinate axes 1', axisOrigin1.clone().add(new THREE.Vector3(-0.55, 0.22, 0.02)), { fontSize: '12px', color: '#17c900', background: 'rgba(255,255,255,0.75)' }),
  x1: addLabel('x<sub>1</sub>', x1Tip, { fontSize: '14px', color: '#16c900', bold: true }),
  y1: addLabel('y<sub>1</sub>', y1Tip, { fontSize: '14px', color: '#16c900', bold: true }),
  z1: addLabel('z<sub>1</sub>', z1Tip, { fontSize: '14px', color: '#16c900', bold: true }),

  camera2: setSerif(addLabel('Camera 2', new THREE.Vector3(), { fontSize: '34px', color: '#000' })),
  image2: addLabel('image plane 2', new THREE.Vector3(), { fontSize: '13px', color: '#111', background: 'rgba(255,255,255,0.78)' }),
  p2: setSerif(addLabel('p<sub>2</sub> ?', new THREE.Vector3(), { fontSize: '44px', color: '#000' }), 'bold'),
  epipolar: addLabel('epipolar line on image plane 2', new THREE.Vector3(), { fontSize: '13px', color: '#d40000', background: 'rgba(255,255,255,0.82)' }),
  rayProjection: addLabel('projection of Camera 1 ray', new THREE.Vector3(), { fontSize: '12px', color: '#d40000', background: 'rgba(255,255,255,0.78)' }),
  e2: addLabel('e<sub>2</sub> = projection of Camera 1', new THREE.Vector3(), { fontSize: '12px', color: '#000', bold: true, background: 'rgba(255,255,255,0.78)' }),
  p1to2: addLabel('&pi;<sub>2</sub>(p<sub>1</sub>)', new THREE.Vector3(), { fontSize: '12px', color: '#008c8c', bold: true, background: 'rgba(255,255,255,0.78)' }),
  pointP2: addLabel('projection of P', new THREE.Vector3(), { fontSize: '12px', color: '#158000', background: 'rgba(255,255,255,0.78)' }),
  x2: addLabel('x<sub>2</sub>', new THREE.Vector3(), { fontSize: '14px', color: '#1d63e8', bold: true }),
  y2: addLabel('y<sub>2</sub>', new THREE.Vector3(), { fontSize: '14px', color: '#1d63e8', bold: true }),
  z2: addLabel('z<sub>2</sub>', new THREE.Vector3(), { fontSize: '14px', color: '#1d63e8', bold: true }),
  axes2: addLabel('coordinate axes 2', new THREE.Vector3(), { fontSize: '12px', color: '#1d63e8', background: 'rgba(255,255,255,0.75)' }),
  RT: setSerif(addLabel('R,T', new THREE.Vector3(), { fontSize: '54px', color: '#18c900' }), 'bold'),
  T: addLabel('T', new THREE.Vector3(), { fontSize: '20px', color: '#18c900', bold: true, background: 'rgba(255,255,255,0.62)' })
};

const demoSteps = [
  {
    title: 'Initial Setup',
    narration: 'Here, you see Camera 1 and Camera 2 with their respecti …',
    rotationCamera2: 0,
    translationCamera2: 0
  },
  {
    title: 'Rotate Camera 2',
    narration: 'As we rotate Camera 2, the image plane changes orientat …',
    rotationCamera2: 45,
    translationCamera2: 0
  },
  {
    title: 'Translate Camera 2',
    narration: 'Translating Camera 2 changes the baseline T. The epipol …',
    rotationCamera2: 45,
    translationCamera2: 5
  }
];

function updateScene() {
  disposeGroup(dynamicGroup);

  const C2 = camera2Center();
  const n2 = camera2Normal();
  const b2 = makeBasisFromNormal(n2);
  const plane2Center = C2.clone().addScaledVector(n2, 2.30)
    .addScaledVector(b2.u, -0.05)
    .addScaledVector(b2.v, 0.04);

  const plane2 = addPlaneOutline(dynamicGroup, plane2Center, n2, 3.10, 3.64, BLACK, 0.029);
  addCamera(dynamicGroup, C2, plane2.corners, n2, -1);
  // [elided] dashed correspondence segments, the red epipolar line, the magenta epipolar plane, and the three projected points
  const origin2 = plane2Center.clone().addScaledVector(n2, 0.10);
  const x2Tip = addArrow(dynamicGroup, origin2, plane2.u.clone().multiplyScalar(-1), 1.12, BLUE, 0.019, 0.92);
  const y2Tip = addArrow(dynamicGroup, origin2, plane2.v, 1.16, BLUE, 0.019, 0.92);
  const z2Tip = addArrow(dynamicGroup, origin2, n2, 0.94, BLUE, 0.019, 0.92);

  const tStart = C1.clone().add(new THREE.Vector3(0.05, -0.58, 0.62));
  const tEnd = C2.clone().add(new THREE.Vector3(-0.05, -0.58, 0.62));
  addArrow(dynamicGroup, tStart, new THREE.Vector3().subVectors(tEnd, tStart), tStart.distanceTo(tEnd), GREEN, 0.026, 1.08);

  const curveStart = C1.clone().add(new THREE.Vector3(1.05, -1.05, 0.92));
  const curveEnd = C2.clone().add(new THREE.Vector3(-1.10, -1.05, 0.92));
  const curveControl = new THREE.Vector3((curveStart.x + curveEnd.x) * 0.5, -3.42, 1.22);
  addCurvedArrow(dynamicGroup, curveStart, curveControl, curveEnd, GREEN, 0.032);

  // [elided] labels.camera2 / image2 / p2 / epipolar / rayProjection / e2 / p1to2 / pointP2 / axes2 are repositioned the same way
  labels.x2.pos.copy(x2Tip);
  labels.y2.pos.copy(y2Tip);
  labels.z2.pos.copy(z2Tip);
  labels.T.pos.copy(tStart).lerp(tEnd, 0.5).add(new THREE.Vector3(0, 0.22, 0.02));
  labels.RT.pos.copy(curveControl).add(new THREE.Vector3(0, -0.20, 0));

  document.getElementById('rotationCamera2Value').textContent = `${Math.round(state.rotationCamera2)}\u00b0`;
  document.getElementById('translationCamera2Value').textContent = state.translationCamera2.toFixed(1);
  document.getElementById('rotationCamera2').value = state.rotationCamera2;
  document.getElementById('translationCamera2').value = state.translationCamera2;

  for (let i = 0; i < 3; i++) {
    document.getElementById(`step${i}`).classList.toggle('active', state.activeStep === i);
  }
  const step = demoSteps[state.activeStep];
  document.getElementById('stepNarration').textContent = step ? step.narration : 'Adjust either slider independently to explore how camera pose changes the epipolar constraint.';
}

const rotationInput = document.getElementById('rotationCamera2');
const translationInput = document.getElementById('translationCamera2');

rotationInput.addEventListener('input', () => {
  state.tween = null;
  state.activeStep = -1;
  state.rotationCamera2 = Number(rotationInput.value);
  updateScene();
});

translationInput.addEventListener('input', () => {
  state.tween = null;
  state.activeStep = -1;
  state.translationCamera2 = Number(translationInput.value);
  updateScene();
});

// [elided] goToStep(i) — eases rotation/translation toward the step target over ~1s, calling updateScene() each frame
document.getElementById('step0').addEventListener('click', () => goToStep(0));
document.getElementById('step1').addEventListener('click', () => goToStep(1));
document.getElementById('step2').addEventListener('click', () => goToStep(2));
window.goToStep = goToStep;

camera.position.set(0.38, 3.05, 9.65);
controls.target.set(0.02, -0.44, 0.24);
camera.zoom = 0.52;
camera.lookAt(controls.target);
camera.updateProjectionMatrix();
controls.update();
HOME_POS.copy(camera.position);
HOME_TARGET.copy(controls.target);
HOME_ZOOM = camera.zoom;

updateScene();
// @FIGURE_CODE_END

