userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>
  w (scale λ)
  <input type="range" id="lambdaSlider" min="0.3" max="3" step="0.1" value="2">
</label>
<label style="flex-direction:row;align-items:center;gap:6px;">
  <input type="checkbox" id="equivClass"> Show equivalence class
</label>
<button id="btnStep1">Step 1: Canonical embedding</button>
<button id="btnStep2">Step 2: Slide along ray</button>
<button id="btnStep3">Step 3: Equivalence class</button>
<div id="readout" style="font-size:12px;margin-top:4px;color:#333;"></div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── Element specs ──
// y-axis: Line + ConeGeometry(0.06,0.18) black, (0,-2,0)->(0,2.2,0)
// x-axis: Line + ConeGeometry(0.06,0.18) black, (0,0,-2)->(0,0,2.2)
// w-axis: Line + ConeGeometry(0.06,0.18) black, (0,0,0)->(4,0,0), tick at X=1
// Heterogeneous plane: PlaneGeometry(4,4) at X=0, #dfe8ea opacity 0.45
// w=1 plane: PlaneGeometry(4,4) EdgesGeometry at X=1, stroke #7a8a8d
// left point: Sphere(0.09) #e02020 + dark #600 outline child, at (0,ptY,ptX)
// canonical point: same, at (1,ptY,ptX)
// representative: same, at (λ,λ*ptY,λ*ptX)
// connector: CylinderGeometry(0.014) dark #444 between (0,ptY,ptX)-(1,ptY,ptX)
// dashed ray: LineDashedMaterial #111 origin->(λ,λ*ptY,λ*ptX)
// equiv rings: TorusGeometry(0.14,0.025) #ff8800 at λ∈{0.5,1,2,3}

const DEFAULT_X = 0.6;
const DEFAULT_Y = 0.7;
let ptX = DEFAULT_X;
let ptY = DEFAULT_Y;
let lambda = 2;
let showEquiv = false;

// ── Axes ──
function makeArrow(from, to, color = 0x111111) {
  const dir = new THREE.Vector3().subVectors(to, from);
  dir.normalize();
  const line = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([from, to]),
    new THREE.LineBasicMaterial({ color })
  );
  scene.add(line);
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(0.06, 0.18, 12),
    new THREE.MeshBasicMaterial({ color })
  );
  cone.position.copy(to);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  scene.add(cone);
}
makeArrow(new THREE.Vector3(0, -2, 0), new THREE.Vector3(0, 2.2, 0));
makeArrow(new THREE.Vector3(0, 0, -2), new THREE.Vector3(0, 0, 2.2));
makeArrow(new THREE.Vector3(0, 0, 0), new THREE.Vector3(4, 0, 0));

// tick at X=1 on w-axis
scene.add(new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(1, -0.12, 0), new THREE.Vector3(1, 0.12, 0)
  ]),
  new THREE.LineBasicMaterial({ color: 0x111111 })
));

// ── Planes ──
const hetPlane = new THREE.Mesh(
  new THREE.PlaneGeometry(4, 4),
  new THREE.MeshBasicMaterial({ color: 0xdfe8ea, transparent: true, opacity: 0.45, side: THREE.DoubleSide })
);
hetPlane.rotation.y = Math.PI / 2;
scene.add(hetPlane);

const w1Outline = new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.PlaneGeometry(4, 4)),
  new THREE.LineBasicMaterial({ color: 0x7a8a8d })
);
w1Outline.position.set(1, 0, 0);
w1Outline.rotation.y = Math.PI / 2;
scene.add(w1Outline);

// ── Points (red sphere + dark outline child) ──
function makePoint() {
  const m = new THREE.Mesh(
    new THREE.SphereGeometry(0.09, 20, 20),
    new THREE.MeshBasicMaterial({ color: 0xe02020 })
  );
  const outline = new THREE.Mesh(
    new THREE.SphereGeometry(0.09, 20, 20),
    new THREE.MeshBasicMaterial({ color: 0x600000 })
  );
  outline.scale.setScalar(1.28);
  outline.renderOrder = -1;
  m.add(outline);
  scene.add(m);
  return m;
}
const leftPoint = makePoint();
const canonPoint = makePoint();
const repPoint = makePoint();

// ── Connector (thick dark cylinder) ──
const connCyl = new THREE.Mesh(
  new THREE.CylinderGeometry(0.014, 0.014, 1, 8),
  new THREE.MeshBasicMaterial({ color: 0x444444 })
);
scene.add(connCyl);
const _up = new THREE.Vector3(0, 1, 0);
function placeConnector(a, b) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  connCyl.position.copy(a).add(b).multiplyScalar(0.5);
  connCyl.scale.set(1, len, 1);
  connCyl.quaternion.setFromUnitVectors(_up, dir.normalize());
}

// ── Dashed ray ──
const dashLine = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3(1, 1, 1)]),
  new THREE.LineDashedMaterial({ color: 0x111111, dashSize: 0.14, gapSize: 0.09 })
);
scene.add(dashLine);

// ── Equivalence rings ──
const equivGroup = new THREE.Group();
const equivLambdas = [0.5, 1, 2, 3];
const equivRings = equivLambdas.map(() => {
  const r = new THREE.Mesh(
    new THREE.TorusGeometry(0.14, 0.025, 10, 28),
    new THREE.MeshBasicMaterial({ color: 0xff8800 })
  );
  equivGroup.add(r);
  return r;
});
equivGroup.visible = false;
scene.add(equivGroup);

// ── Labels ─
addLabel('<i>y</i>', new THREE.Vector3(0, 2.4, 0), { fontSize: '15px', bold: true });
addLabel('<i>x</i>', new THREE.Vector3(0, 0.3, 2.4), { fontSize: '15px', bold: true });
addLabel('<i>w</i>', new THREE.Vector3(4.2, -0.25, 0), { fontSize: '15px', bold: true });
addLabel('1', new THREE.Vector3(1, -0.38, 0), { fontSize: '14px' });
addLabel('Heterogeneous', new THREE.Vector3(-0.3, 0.7, -2.4), { fontSize: '14px', color: '#333' });
addLabel('Homogeneous', new THREE.Vector3(3.4, 1.25, 1.7), { fontSize: '14px', color: '#333' });

const lblLeft = addLabel('(<i>x</i>,<i>y</i>)', new THREE.Vector3(0, ptY + 0.28, ptX), {
  fontSize: '16px', bold: true, offset: [-26, -12]
});
const lblCanon = addLabel('(<i>x</i>,<i>y</i>,1)', new THREE.Vector3(1, ptY - 0.32, ptX), {
  fontSize: '16px', bold: true, offset: [12, 18]
});
const lblRep = addLabel('(λ<i>x</i>,λ<i>y</i>,λ)', new THREE.Vector3(lambda, lambda * ptY + 0.28, lambda * ptX), {
  fontSize: '16px', bold: true, offset: [22, -14]
});

// ── Readout (panel only) ──
const readoutDiv = document.getElementById('readout');
function updateReadout() {
  readoutDiv.innerHTML = `(x/w, y/w) = (${ptX.toFixed(2)}, ${ptY.toFixed(2)})`;
}

// ── Update ──
function updateScene() {
  leftPoint.position.set(0, ptY, ptX);
  canonPoint.position.set(1, ptY, ptX);
  repPoint.position.set(lambda, lambda * ptY, lambda * ptX);

  placeConnector(new THREE.Vector3(0, ptY, ptX), new THREE.Vector3(1, ptY, ptX));

  const dp = dashLine.geometry.attributes.position;
  dp.setXYZ(0, 0, 0, 0);
  dp.setXYZ(1, lambda, lambda * ptY, lambda * ptX);
  dp.needsUpdate = true;
  dashLine.computeLineDistances();

  const rd = new THREE.Vector3(1, ptY, ptX).normalize();
  equivRings.forEach((ring, i) => {
    const l = equivLambdas[i];
    ring.position.set(l, l * ptY, l * ptX);
    ring.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), rd);
  });

  lblLeft.pos.set(0, ptY + 0.28, ptX);
  lblCanon.pos.set(1, ptY - 0.32, ptX);
  lblRep.pos.set(lambda, lambda * ptY + 0.28, lambda * ptX);

  const col = showEquiv ? 0xff8800 : 0xe02020;
  [leftPoint, canonPoint, repPoint].forEach(p => p.material.color.set(col));

  updateReadout();
}

// ── UI ──
const sliderEl = document.getElementById('lambdaSlider');
sliderEl.addEventListener('input', () => { lambda = parseFloat(sliderEl.value); updateScene(); });

const equivEl = document.getElementById('equivClass');
equivEl.addEventListener('change', () => {
  showEquiv = equivEl.checked;
  equivGroup.visible = showEquiv;
  updateScene();
});

// ── Drag the 2D point on the Heterogeneous plane ──
const raycaster = new THREE.Raycaster();
const pointer2 = new THREE.Vector2();
let dragging = false;
const hetPlaneMath = new THREE.Plane(new THREE.Vector3(1, 0, 0), 0);
const hitPt = new THREE.Vector3();

canvas.addEventListener('pointerdown', (e) => {
  const rect = canvas.getBoundingClientRect();
  pointer2.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  pointer2.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  raycaster.setFromCamera(pointer2, camera);
  if (raycaster.ray.distanceToPoint(leftPoint.position) < 0.28) {
    dragging = true;
    controls.enabled = false;
    e.preventDefault();
  }
});
canvas.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  const rect = canvas.getBoundingClientRect();
  pointer2.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  pointer2.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  raycaster.setFromCamera(pointer2, camera);
  if (raycaster.ray.intersectPlane(hetPlaneMath, hitPt)) {
    ptY = THREE.MathUtils.clamp(hitPt.y, -1.8, 1.8);
    ptX = THREE.MathUtils.clamp(hitPt.z, -1.8, 1.8);
    updateScene();
  }
});
canvas.addEventListener('pointerup', () => {
  if (dragging) { dragging = false; controls.enabled = true; }
});

// ── Demo steps ──
function goToStep(step) {
  if (step === 1) { lambda = 1; sliderEl.value = '1'; showEquiv = false; equivEl.checked = false; equivGroup.visible = false; }
  else if (step === 2) { lambda = 2.5; sliderEl.value = '2.5'; showEquiv = false; equivEl.checked = false; equivGroup.visible = false; }
  else if (step === 3) { lambda = 2; sliderEl.value = '2'; showEquiv = true; equivEl.checked = true; equivGroup.visible = true; }
  updateScene();
}
document.getElementById('btnStep1').addEventListener('click', () => goToStep(1));
document.getElementById('btnStep2').addEventListener('click', () => goToStep(2));
document.getElementById('btnStep3').addEventListener('click', () => goToStep(3));

// ── Interactive explainers ──
registerInteractive(leftPoint, {
  title: '2D Point (x, y)',
  body: 'The heterogeneous (standard Euclidean) representation. Drag it to swing the entire homogeneous ray through the origin.',
  tooltip: 'Drag to move the 2D point'
});
registerInteractive(canonPoint, {
  title: 'Canonical point (x, y, 1)',
  body: 'The canonical embedding of (x,y): append w=1. It always lies on the w=1 plane.',
  tooltip: 'Canonical homogeneous embedding'
});
registerInteractive(repPoint, {
  title: 'General representative (λx, λy, λ)',
  body: 'Any scalar multiple of (x,y,1) represents the same 2D point; dividing by w recovers (x,y).',
  tooltip: 'Scaled representative on the ray'
});

// ── Camera ──
setCameraView({
  projection: 'orthographic',
  azimuthDeg: 112,
  elevationDeg: 16,
  heightFraction: 0.7
});

updateScene();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original 2D figure, making a generation plan, generating an interactive 3D figure, and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

Example 1 → pass
{"failure_modes":["Color-Wrong","Missing-Labels"],"geometry_accuracy":4,"interactivity_usability":4,"faithfulness":3,"label_quality":3,"concept_accuracy":4,"overall_average":3.6,"notes":"Interactive elements are mostly functional, but visual and label details do not fully align with the source."}
{"next_step":"pass","rationale":"Scores are consistently high (mostly 4s), failure modes are minor visual polish issues, and concept and interactivity are solid — further iteration is unlikely to yield meaningful improvement."}

Example 2 → refine_generation
{"failure_modes":["Color-Wrong","Scale-Wrong","Interaction-Missing","Camera-Wrong"],"geometry_accuracy":3,"interactivity_usability":3,"faithfulness":3,"label_quality":3,"concept_accuracy":3,"overall_average":3,"notes":"The rendering contains overlapping text, varying colors, and lacks precise interactivity, making it somewhat difficult to grasp the 3D representation."}
{"next_step":"refine_generation","rationale":"The concept is present but execution has multiple implementation-level issues — color mismatches, missing interactions, wrong camera angle, scale errors — all fixable by the generator without changing the plan."}

Example 3 → fix_plan
{"failure_modes":["Missing-Labels","Interaction-Missing","Camera-Wrong","Color-Wrong","Concept-Misunderstood"],"geometry_accuracy":2,"interactivity_usability":2,"faithfulness":2,"label_quality":2,"concept_accuracy":2,"overall_average":2,"notes":"Discrepancies in elements and labels, with limited interactivity and conceptual errors."}
{"next_step":"fix_plan","rationale":"Concept-Misunderstood failure mode and all scores at 2/5 indicate the plan failed to correctly decompose the figure — the generator cannot fix a fundamentally wrong conceptual structure."}
